        hud.levelLabel=Text("Level",header.transform,"HEDEF RENK",11,new Vector2(300,18),new Vector2(-43,28),s,TextAlignmentOptions.Left);hud.levelLabel.characterSpacing=2;hud.levelLabel.color=new Color(.85f,.66f,.36f);hud.targetName=Text("Target",header.transform,"Turuncu",23,new Vector2(300,28),new Vector2(-43,5),s,TextAlignmentOptions.Left);
        var track=Panel("Fill Track",header.transform,new Vector2(300,8),new Vector2(.5f,.5f),new Vector2(-43,-25),new Color(1,1,1,.12f),s);hud.meter=Panel("Fill",track.transform,new Vector2(300,8),new Vector2(.5f,.5f),Vector2.zero,new Color(.78f,.36f,.92f),s);hud.meter.type=UnityEngine.UI.Image.Type.Filled;hud.meter.fillMethod=UnityEngine.UI.Image.FillMethod.Horizontal;hud.meter.fillAmount=0;hud.matchLabel=Text("Match",header.transform,"—",17,new Vector2(58,24),new Vector2(138,-23),s);hud.retry=Button("Retry",header.transform,"↻",new Vector2(40,40),new Vector2(170,16),s,out var retryText);retryText.fontSize=27;
        var tag=Panel("Target Tag",go.transform,new Vector2(136,29),new Vector2(.5f,.5f),Vector2.zero,new Color(.12f,.085f,.05f,.92f),s);hud.targetTag=tag.rectTransform;Text("Label",tag.transform,"HEDEF RENK",11,new Vector2(110,25),new Vector2(9,0),s);hud.tagDot=Panel("Swatch",tag.transform,new Vector2(10,10),new Vector2(.5f,.5f),new Vector2(-53,0),new Color(1,.45f,.02f),s);
