        hud.guide=Rect("Tutorial",go.transform,Vector2.zero,new Vector2(.5f,.5f),Vector2.zero).gameObject;hud.hand=Rect("Hand",hud.guide.transform,new Vector2(115,138),new Vector2(.5f,.5f),Vector2.zero);var hand=hud.hand.gameObject.AddComponent<UnityEngine.UI.Image>();hand.sprite=s.hand;hand.raycastTarget=false;hand.preserveAspect=true;
        hud.startPanel=Overlay("Start",hud.safeArea,s,.25f);var title=Text("Title",hud.startPanel.transform,"PIGMENT",57,new Vector2(430,85),new Vector2(0,35),s);title.characterSpacing=8;Text("Subtitle",hud.startPanel.transform,"Renkleri karıştır, hedef rengi tuttur",16,new Vector2(420,35),new Vector2(0,-28),s);hud.play=Button("Play",hud.startPanel.transform,"BAŞLA",new Vector2(200,58),new Vector2(0,-110),s,out _);
        hud.resultPanel=Overlay("Result",hud.safeArea,s,.35f);var card=Panel("Result Card",hud.resultPanel.transform,new Vector2(370,420),new Vector2(.5f,.5f),Vector2.zero,new Color(.13f,.085f,.06f,.98f),s,true);hud.stars=Text("Stars",card.transform,"★  ★  ★",42,new Vector2(330,55),new Vector2(0,155),s);hud.percent=Text("Percent",card.transform,"%100",68,new Vector2(320,88),new Vector2(0,90),s);hud.verdict=Text("Verdict",card.transform,"Kusursuz karışım!",22,new Vector2(330,44),new Vector2(0,27),s);hud.want=Panel("Target Color",card.transform,new Vector2(68,68),new Vector2(.5f,.5f),new Vector2(-58,-48),Color.white,s);hud.got=Panel("Your Color",card.transform,new Vector2(68,68),new Vector2(.5f,.5f),new Vector2(58,-48),Color.white,s);Text("Target Caption",card.transform,"Hedef",13,new Vector2(85,24),new Vector2(-58,-96),s);Text("Your Caption",card.transform,"Senin",13,new Vector2(85,24),new Vector2(58,-96),s);hud.next=Button("Continue",card.transform,"Sonraki renk",new Vector2(290,55),new Vector2(0,-159),s,out hud.nextLabel);
