    public static void InstallIcons(PigmentHud hud){
        hud.retry.GetComponentInChildren<TextMeshProUGUI>().text="";
        if(!hud.retry.transform.Find("Refresh Icon"))Icon("Refresh Icon",hud.retry.transform,Vector2.zero,24,true);
        hud.stars.text="";hud.resultStarIcons=new PigmentIcon[3];
        for(int i=0;i<3;i++){var old=hud.stars.transform.Find("Star "+i);hud.resultStarIcons[i]=old?old.GetComponent<PigmentIcon>():Icon("Star "+i,hud.stars.transform,new Vector2((i-1)*63,0),42,false);}
        hud.totalStars.text="21 / 21";
        if(!hud.totalStars.transform.Find("Star"))Icon("Star",hud.totalStars.transform,new Vector2(-86,0),32,false);
        EditorUtility.SetDirty(hud);
    }
    static PigmentIcon Icon(string name,Transform parent,Vector2 pos,float size,bool refresh){var r=Rect(name,parent,Vector2.one*size,new Vector2(.5f,.5f),pos);var icon=r.gameObject.AddComponent<PigmentIcon>();icon.refresh=refresh;icon.raycastTarget=false;icon.color=new Color(1,.82f,.4f);return icon;}

}
